Q: REST API GET method A: <pre><code>class Networking{

    static let net = Networking()

    //(1) MARK: - LicenseNetwork
    func LicenseNetwork(vc: UIViewController,url: String,key: String,complition: @escaping(Data?,Bool,String)-&gt; Void){
        let timeoutInterval: TimeInterval = 60.0
        let param: Parameters = [&quot;key&quot;: key]

        // Timer to handle timeout
        var timeoutTimer: Timer? = Timer.scheduledTimer(withTimeInterval: timeoutInterval, repeats: false) { _ in
            print(&quot;Request timed out&quot;)

            DispatchQueue.main.async {

                UtilityFunction_login().simpleAlert(vc: vc, title: &quot;Alert&quot;, message: &quot;Request Timed Out(1)&quot;)
            }

            complition(nil, false, &quot;Request Timed Out&quot;)
        }
        let response = AF.request(url,method: .get,parameters: param)
        response.response { DataResponse in timeoutTimer?.invalidate()
            guard let statusCode = response.response?.statusCode else {
                complition(nil, false, &quot;Unknown Error&quot;)
                return
            }

            print(&quot;Status Code: \(statusCode)&quot;)

            if statusCode == 200 {
                complition(response.data, true, &quot;Success&quot;)
            } else {
                complition(nil, false, &quot;Error: Status Code \(statusCode)&quot;)
                DispatchQueue.main.async {
                    let errorMessage: String

                    switch statusCode {
                    case 400:
                        errorMessage = &quot;Bad Request (400)(1): The request could not be understood by the server.&quot;
                    case 401:
                        errorMessage = &quot;Unauthorized (401)(1): You are not authorized to access this resource.&quot;
                    case 403:
                        errorMessage = &quot;Forbidden (403)(1): You don't have permission to access this resource.&quot;
                    case 404:
                        errorMessage = &quot;Not Found (404)(1): The requested resource could not be found.&quot;
                    case 500:
                        errorMessage = &quot;Internal Server Error (500)(1): Something went wrong on the server.&quot;
                    case 503:
                        errorMessage = &quot;Service Unavailable (503)(1): The server is currently unable to handle the request.&quot;
                    default:
                        errorMessage = &quot;Unexpected Error (\(statusCode))(1): Please try again later.&quot;
                    }

                    UtilityFunction_login().simpleAlert(vc: vc, title: &quot;Alert&quot;, message: errorMessage)
                }
            }
        }
    }
}


